/** Exact game framebuffer stream. All actions still go through the authenticated CLI. */
export declare const nativeViewerHtml = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width\"><title>MCT \u00B7 Minecraft game view</title><style>body{margin:0;background:#101820;color:#edf3f5;font:15px system-ui}header{padding:14px 20px;display:flex;justify-content:space-between}main{display:grid;place-items:center;height:calc(100vh - 80px)}img{max-width:100%;max-height:100%;image-rendering:auto}small{color:#b6ced3}</style><header><b>MCT \u00B7 Live Minecraft renderer</b><small id=\"status\">Connecting\u2026</small></header><main><img id=\"frame\" alt=\"Live game screen\"></main><script>\nconst query=new URLSearchParams(location.search),img=document.querySelector('#frame'),status=document.querySelector('#status');let stopped=document.hidden,blobUrl,inFlight=false,timer;\nasync function refresh(){if(stopped||inFlight)return;inFlight=true;try{const response=await fetch('/native-frame?'+query.toString(),{cache:'no-store'});if(!response.ok){const data=await response.json();throw Error(data.error?.message||response.statusText)}const blob=await response.blob();if(stopped)return;const next=URL.createObjectURL(blob);img.src=next;if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl=next;status.textContent='Exact game pixels \u00B7 '+new Date().toLocaleTimeString();}catch(error){status.textContent=error.message}finally{inFlight=false;if(!stopped){clearTimeout(timer);timer=setTimeout(refresh,750)}}}\ndocument.addEventListener('visibilitychange',()=>{stopped=document.hidden;clearTimeout(timer);if(!stopped)refresh()});addEventListener('pagehide',()=>{stopped=true;clearTimeout(timer);if(blobUrl)URL.revokeObjectURL(blobUrl)});refresh();\n</script></html>";
